// Load requirements
const log = require('logToConsole');
const set_cookie = require('setCookie');
const localStorage = require('localStorage');
const get_cookie = require('getCookieValues');
const sha256 = require('sha256');
const string = require('makeString');
const fromBase64 = require('fromBase64');
const toBase64 = require('toBase64');
const createQueue = require('createQueue');
const makeString = require('makeString');


if (data.text1) {
    data.text3 = data.text3 * 60 * 60 * 24;

    // Cookie
    if (data.radio1 == 1) {
        if (get_cookie(data.text2).length == 0) {
            //Specify Cookie Options
            const options = {
                domain: data.domain,
                'max-age': data.text3,
                path: "/",
                samesite: 'lax',
                secure: true
            };
            //Creat a hash and write the cookie
            sha256(data.text1, (digest) => {
                var coo = digest;
                if (data.checkbox1) {
                    coo = toBase64(coo);
                    set_cookie(data.text2, coo.substring(0, coo.length - 2), options);
                } else {
                    set_cookie(data.text2, coo, options);
                }
                data.gtmOnSuccess();
            }, data.gtmOnFailure);
        } else {
            if (data.checkbox2) {
                const options = {
                    domain: data.domain,
                    'max-age': data.text3,
                    path: "/",
                    samesite: 'lax',
                    secure: true
                };
                //Creat a hash and write the cookie
                sha256(data.text1, (digest) => {
                    var coo = digest;
                    if (data.checkbox1) {
                        coo = toBase64(coo);
                        set_cookie(data.text2, coo.substring(0, coo.length - 2), options);
                    } else {
                        set_cookie(data.text2, coo, options);
                    }
                    data.gtmOnSuccess();
                }, data.gtmOnFailure);
            }

        }
    }

    // DataLayer
    if (data.radio1 == 2) {
        //Creat a hash and write the to dataLayer
        sha256(data.text1, (digest) => {
            var coo = digest;
            if (data.checkbox1) {
                coo = toBase64(coo);
                const dataLayerPush = createQueue('dataLayer');
                dataLayerPush({
                    'sha3_value': makeString(coo.substring(0, coo.length - 2)),
                    'event': 'sha3'
                });
            } else {
                const dataLayerPush = createQueue('dataLayer');
                dataLayerPush({
                    'sha3_value': makeString(coo),
                    'event': 'sha3'
                });
            }
            data.gtmOnSuccess();
        }, data.gtmOnFailure);
    }

    // Local Storage
    if (data.radio1 == 0) {
        if (localStorage) {
            if (!localStorage.getItem(data.text21)) {
                //Creat a hash and write the cookie
                sha256(data.text1, (digest) => {
                    var coo = digest;
                    if (data.checkbox1) {
                        coo = toBase64(coo);
                        localStorage.setItem(data.text21, coo.substring(0, coo.length - 2));
                    } else {
                        localStorage.setItem(data.text21, coo);
                    }
                    data.gtmOnSuccess();
                }, data.gtmOnFailure);
            } else {
                if (data.checkbox2) {
                    sha256(data.text1, (digest) => {
                        var coo = digest;
                        if (data.checkbox1) {
                            coo = toBase64(coo);
                            localStorage.setItem(data.text21, coo.substring(0, coo.length - 2));
                        } else {
                            localStorage.setItem(data.text21, coo);
                        }
                        data.gtmOnSuccess();
                    }, data.gtmOnFailure);
                }
            }
        } else {
            log("No local storage - GTM");
        }
    }
    // Call data.gtmOnSuccess when the tag is finished.
    data.gtmOnSuccess();
} else {
    data.gtmOnFailure();
}


